const TZ = 'Europe/Helsinki';
const body = (n) => { try { const j = $(n).first().json; return j.statusCode === 200 ? String(j.body || '') : ''; } catch (e) { return ''; } };
const parse = (s, d) => { try { const v = JSON.parse(s); return v || d; } catch (e) { return d; } };
const now = $now.setZone(TZ);
const ymd = (n) => now.plus({ days: n }).toFormat('yyyy-LL-dd');
const SCHEMA = {"type": "object", "properties": {"title": {"type": "string"}, "intro_ar": {"type": "string"}, "new_words": {"type": "array", "items": {"type": "object", "properties": {"fi": {"type": "string"}, "ar": {"type": "string"}, "en": {"type": "string"}, "example_fi": {"type": "string"}, "example_ar": {"type": "string"}, "mnemonic_ar": {"type": "string"}}, "required": ["fi", "ar", "en", "example_fi", "example_ar", "mnemonic_ar"], "additionalProperties": false}}, "sentences": {"type": "array", "items": {"type": "object", "properties": {"fi": {"type": "string"}, "ar": {"type": "string"}}, "required": ["fi", "ar"], "additionalProperties": false}}, "grammar_ar": {"type": "string"}, "real_life": {"type": "object", "properties": {"scenario_ar": {"type": "string"}, "lines": {"type": "array", "items": {"type": "object", "properties": {"who": {"type": "string"}, "fi": {"type": "string"}, "ar": {"type": "string"}}, "required": ["who", "fi", "ar"], "additionalProperties": false}}}, "required": ["scenario_ar", "lines"], "additionalProperties": false}, "yki": {"type": "object", "properties": {"skill": {"type": "string"}, "task_fi": {"type": "string"}, "task_ar": {"type": "string"}}, "required": ["skill", "task_fi", "task_ar"], "additionalProperties": false}, "question": {"type": "object", "properties": {"fi": {"type": "string"}, "ar": {"type": "string"}}, "required": ["fi", "ar"], "additionalProperties": false}, "homework_ar": {"type": "string"}}, "required": ["title", "intro_ar", "new_words", "sentences", "grammar_ar", "real_life", "yki", "question", "homework_ar"], "additionalProperties": false};
const res = $input.first().json;
if (res.error || !Array.isArray(res.content)) throw new Error('Claude error: ' + JSON.stringify(res.error || res).slice(0, 300));
const lesson = res.content.filter(c => c.type === 'text').map(c => c.text).join('');
const SYSTEM = 'You are a strict Finnish language proofreader and Egyptian-Arabic reviewer. You receive a lesson as JSON. Fix every error in the Finnish (spelling, vowel harmony, case endings, partitive, verb forms, time expressions, word meaning) and any wrong or unnatural Egyptian-Arabic/English meaning. Keep the same JSON structure, the same number of items and the same length. Do not add new content. Return only the corrected JSON.';
const request = { model: "claude-opus-5-5", max_tokens: 6000, output_config: { format: { type: 'json_schema', schema: SCHEMA } }, system: SYSTEM, messages: [{ role: 'user', content: lesson }] };
return [{ json: { body: request } }];

const TZ = 'Europe/Helsinki';
const body = (n) => { try { const j = $(n).first().json; return j.statusCode === 200 ? String(j.body || '') : ''; } catch (e) { return ''; } };
const parse = (s, d) => { try { const v = JSON.parse(s); return v || d; } catch (e) { return d; } };
const now = $now.setZone(TZ);
const ymd = (n) => now.plus({ days: n }).toFormat('yyyy-LL-dd');
const read = (r) => JSON.parse(r.content.filter(c => c.type === 'text').map(c => c.text).join(''));
let L, checked = true;
try { L = read($('Claude check').first().json); }
catch (e) { checked = false; L = read($('Claude lesson').first().json); }
const state = parse(body('Get vocab'), { words: {} });
if (!state.words) state.words = {};
let added = 0;
for (const w of L.new_words) {
  const key = String(w.fi || '').trim().toLowerCase();
  if (!key || state.words[key]) continue;
  state.words[key] = { fi: w.fi.trim(), ar: w.ar, en: w.en, example: w.example_fi, mnemonic: w.mnemonic_ar, chapter: 'daily ' + ymd(0), box: 1, due: ymd(1), added: ymd(0), lapses: 0, seen: 0 };
  added++;
}
const words = L.new_words.map((w, i) => `${i + 1}. ${w.fi} = ${w.ar} (${w.en})
   ${w.example_fi} = ${w.example_ar}
   💡 ${w.mnemonic_ar}`).join('
');
const sents = L.sentences.map(s => `• ${s.fi}
  ${s.ar}`).join('
');
const dlg = L.real_life.lines.map(l => `${l.who}: ${l.fi}
   ${l.ar}`).join('
');
const msg = `📘 ${L.title}
${L.intro_ar}

🆕 كلمات النهارده
${words}

🧩 جمل
${sents}

📐 قاعدة
${L.grammar_ar}

🏪 موقف حقيقي
${L.real_life.scenario_ar}
${dlg}

🎯 YKI (${L.yki.skill})
${L.yki.task_fi}
${L.yki.task_ar}

📝 واجب: ${L.homework_ar}

❓ سؤال واحد:
${L.question.fi}
${L.question.ar}${checked ? '' : '

(⚠️ الدرس ماتراجعش لغوياً الليلة)'}`;
const md = `# ${L.title}

Date: ${ymd(0)}

${msg}
`;
return [{ json: { msg, lessonUrl: "https://YOUR-NEXTCLOUD/remote.php/dav/files/YOUR-USER/FinnishBot" + '/lessons/' + ymd(0) + '.md', lessonMd: md, vocabPayload: JSON.stringify(state, null, 1), added } }];

const text = String($('Finalize').first().json.msg || '').trim() || '…';
const chat_id = "REPLACE_OWNER_CHAT_ID";
const out = [];
let rest = text;
while (rest.length > 3900) {
  let cut = rest.lastIndexOf('\n', 3900);
  if (cut < 1000) cut = 3900;
  out.push(rest.slice(0, cut));
  rest = rest.slice(cut).replace(/^\n+/, '');
}
out.push(rest);
return out.map(t => ({ json: { chat_id, text: t } }));
